def carregar_modelos(apps, schema_editor):
    ModeloFVS = apps.get_model("cadastros", "ModeloFVS")
    ItemModeloFVS = apps.get_model("cadastros", "ItemModeloFVS")
    for dados in MODELOS:
        modelo, _ = ModeloFVS.objects.get_or_create(
            nome=dados["nome"],
            defaults={
                "disciplina": dados["disciplina"],
                "normas_referencias": dados["normas"],
                "revisao": dados["revisao"],
                "ativo": True,
            },
        )
        if not modelo.itens.exists():
            ItemModeloFVS.objects.bulk_create([
                ItemModeloFVS(
                    modelo=modelo,
                    ordem=int(item[0]),
                    item_verificacao=item[1],
                    metodo_instrumento=item[2] or "",
                    criterio_aceite=item[3] or "",
                    tolerancia=item[4] or "",
                    obrigatorio=True,
                )
                for item in dados["itens"]
            ])


